import sys
data = sys.stdin.read().split()
n = int(data[0])
wins = {('R', 'G'), ('G', 'B'), ('B', 'R')}
win_a = win_b = 0
for i in range(n):
    a, b = data[1 + 2*i:3 + 2*i]
    if a == b:
        continue
    if (a, b) in wins:
        win_a += 1
    else:
        win_b += 1
print("A" if win_a > win_b else "B" if win_b > win_a else "draw")
